codon_table = {
'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L',
'ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V',
'TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}

def translate(s):
    return "".join(codon_table.get(s[i:i+3],"?") for i in range(0,len(s)-2,3))

def find_orfs(s, minlen=100):
    res=[]
    for frame in range(3):
        t = translate(s[frame:])
        # find ORFs between stops
        start=None
        aa_start=0
        for i,aa in enumerate(t):
            if aa=='*':
                if start is not None and (i-start)*3>=minlen:
                    res.append((frame,start,i,start*3+frame,i*3+frame))
                start=None
            elif aa=='M' and start is None:
                start=i
        if start is not None:
            res.append((frame,start,len(t),start*3+frame,len(t)*3+frame))
    return res

print("Forward ORFs (>=100nt):")
for r in find_orfs(seq):
    print(r)
print()
print("Reverse ORFs (>=100nt):")
for r in find_orfs(rc(seq)):
    print(r)
