seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"):
            continue
        seq += line.strip()
L = len(seq)

motif = "GAGTTCCCCGCGCCAGCGGGGATAAACCG"
def hamming(a,b): return sum(1 for x,y in zip(a,b) if x!=y)

# approximate, greedy non-overlapping copies allowing <=6 mismatches
hits=[]
pos=0
while pos <= L-len(motif):
    k=pos
    while k <= L-len(motif):
        d=hamming(seq[k:k+len(motif)],motif)
        if d<=6:
            hits.append((k,d,seq[k:k+len(motif)]))
            pos=k+len(motif)
            break
        k+=1
    else:
        break
print("approximate copies:", len(hits))
for h in hits:
    print(h[0], "mism=%d"%h[1], h[2])
